use serious_game_wasmtime_sandbox::{read_from_guest, write_to_guest, AccessError, Sandbox};

#[test]
fn safe_read_inside_guest_still_works() {
    let mut sandbox = Sandbox::new();
    sandbox.seed_guest(b"HELLO_GUEST_MEMORY");

    let data = read_from_guest(&sandbox, 0, 5).unwrap();
    assert_eq!(&data, b"HELLO");
}

#[test]
fn read_up_to_guest_boundary_still_works() {
    let mut sandbox = Sandbox::new();
    sandbox.seed_guest(b"HELLO_GUEST_MEMORY");

    let data = read_from_guest(&sandbox, 59, 5).unwrap();
    assert_eq!(data.len(), 5);
}

#[test]
fn safe_write_inside_guest_still_works() {
    let mut sandbox = Sandbox::new();

    write_to_guest(&mut sandbox, 2, b"ABC").unwrap();
    assert_eq!(&sandbox.guest_slice()[2..5], b"ABC");
}

#[test]
fn write_up_to_guest_boundary_still_works() {
    let mut sandbox = Sandbox::new();

    write_to_guest(&mut sandbox, 61, b"XYZ").unwrap();
    assert_eq!(&sandbox.guest_slice()[61..64], b"XYZ");
}

#[test]
fn read_after_guest_is_blocked() {
    let sandbox = Sandbox::new();

    let result = read_from_guest(&sandbox, 64, 2);
    assert!(matches!(result, Err(AccessError::OutOfBounds)));
}

#[test]
fn write_after_guest_is_blocked() {
    let mut sandbox = Sandbox::new();
    let suffix_before = sandbox.host_suffix().to_vec();

    let result = write_to_guest(&mut sandbox, 64, b"OWN");
    assert!(matches!(result, Err(AccessError::OutOfBounds)));
    assert_eq!(sandbox.host_suffix(), suffix_before.as_slice());
}

#[test]
fn read_past_end_of_guest_is_blocked() {
    let sandbox = Sandbox::new();

    let result = read_from_guest(&sandbox, 63, 2);
    assert!(matches!(result, Err(AccessError::OutOfBounds)));
}

#[test]
fn write_past_end_of_guest_is_blocked() {
    let mut sandbox = Sandbox::new();
    let suffix_before = sandbox.host_suffix().to_vec();

    let result = write_to_guest(&mut sandbox, 62, b"WXYZ");
    assert!(matches!(result, Err(AccessError::OutOfBounds)));
    assert_eq!(sandbox.host_suffix(), suffix_before.as_slice());
}

#[test]
fn zero_length_read_is_rejected() {
    let sandbox = Sandbox::new();

    let result = read_from_guest(&sandbox, 0, 0);
    assert!(matches!(result, Err(AccessError::InvalidLength)));
}

#[test]
fn empty_write_is_rejected() {
    let mut sandbox = Sandbox::new();

    let result = write_to_guest(&mut sandbox, 0, b"");
    assert!(matches!(result, Err(AccessError::InvalidLength)));
}
